import React, { useEffect, useState } from "react";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { useNavigate, useLocation } from "react-router-dom";

export default function CustomerDetail() {
  const { state } = useLocation();
  const [data, setData] = useState(state?.data);
  const navigate = useNavigate();

  const handleInputChange = (event) => {
    const { name, value } = event?.target;

    setData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  return (
    <div className="customer_detail">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Customer details</h3>
      </div>
      <div className="customer_detail__content">
        <div>
          <img
            src={data?.image}
            alt="Customer Profile"
            className="customer_detail__content__profile"
          />
        </div>
        <div className="customer_detail__content">
          <div className="customer_detail__content__name">
            <div className="customer_detail__content__name__first_name">
              <label htmlFor="Fname">First Name</label>
              <input
                type="text"
                id="first_name"
                name="first_name"
                value={data?.first_name}
                onChange={handleInputChange}
              />
            </div>
            <div className="customer_detail__content__name__last_name">
              <label htmlFor="Lname">Last Name</label>
              <input
                type="text"
                id="last_name"
                name="last_name"
                value={data?.last_name}
                onChange={handleInputChange}
              />
            </div>
          </div>
          <div className="customer_detail__content__email">
            <label htmlFor="Email">Email</label>
            <input
              type="text"
              id="email"
              name="email"
              value={data?.email}
              style={{ textDecoration: "underline" }}
              onChange={handleInputChange}
            />
          </div>
          <div className="customer_detail__content__contact">
            <label htmlFor="contact">Contact</label>
            <input
              type="text"
              id="phone"
              name="phone"
              value={data?.phone}
              onChange={handleInputChange}
            />
          </div>
          <div className="customer_detail__content__gender_DOB">
            <div className="customer_detail__content_DOB">
              <label htmlFor="DOB">Date of birth</label>
              <input
                type="text"
                id="date_of_birth"
                name="date_of_birth"
                placeholder="DD-MM-YYYY"
                value={data?.dob}
              />
            </div>
            <div className="customer_detail__content_gender">
              <label htmlFor="gen">Gender</label>
              <input
                type="text"
                id="gender"
                name="gender"
                value={data?.gender}
                onChange={handleInputChange}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
